// La rama de las pruebas. Marca la ejecución como simulacro para que el flujo
// pare justo antes de crear contenedores de imagen: probar a mano no puede
// publicar por accidente, y el cron no puede quedarse en simulacro por un flag
// olvidado, porque este nodo sólo existe en la rama manual.
//
// Para publicar de verdad a mano (recuperar un día perdido), pon false aquí.
return [{ json: { simular: true } }];

// ── Modo ─────────────────────────────────────────────────────────────────────
// El nodo «Modo: simulacro» sólo existe en la rama manual, así que referenciarlo
// desde el cron lanza. Eso es exactamente lo que se quiere: si no está, no hay
// simulacro.
let simular = false;
try {
  const m = $('Modo: simulacro').first();
  if (m && m.json) simular = Boolean(m.json.simular);
} catch (e) {
  simular = false;
}

// ── Topes de Meta (doc de Content Publishing, 6 nov 2026) ────────────────────
const LIMITE_HIJOS = 20;
const LIMITE_PIE = 2200;
const LIMITE_ETIQUETAS = 30;
const LIMITE_MENCIONES = 20;

const p = $input.first().json;
if (!p || typeof p !== 'object') {
  throw new Error('La respuesta de /api/promo no es un objeto JSON.');
}
for (const k of ['portada', 'imagenes', 'titulos', 'texto', 'enlace']) {
  if (!p[k]) throw new Error('Paquete incompleto: falta ' + k + '.');
}
if (!Array.isArray(p.imagenes) || !Array.isArray(p.titulos)) {
  throw new Error('El paquete trae imagenes o titulos con forma invalida.');
}
if (p.titulos.length !== p.imagenes.length) {
  throw new Error('El paquete no cuadra: ' + p.titulos.length + ' titulos para ' + p.imagenes.length + ' eventos.');
}

// Un dia con menos de 3 planes no merece un carrusel: sale pobre y gasta cupo.
if (p.imagenes.length < 3) {
  throw new Error('Pocos planes para publicar: el paquete trae ' + p.imagenes.length + ' y el minimo es 3. No se publica.');
}

// ── Pie ──────────────────────────────────────────────────────────────────────
const pie = String(p.texto);
if (pie.length > LIMITE_PIE) {
  throw new Error('El pie tiene ' + pie.length + ' caracteres y Meta admite ' + LIMITE_PIE + '.');
}
const etiquetas = (pie.match(/#[^\s#]+/g) || []).length;
if (etiquetas > LIMITE_ETIQUETAS) {
  throw new Error('El pie lleva ' + etiquetas + ' etiquetas y Meta admite ' + LIMITE_ETIQUETAS + '.');
}
const menciones = (pie.match(/@[A-Za-z0-9._]+/g) || []).length;
if (menciones > LIMITE_MENCIONES) {
  throw new Error('El pie lleva ' + menciones + ' menciones y Meta admite ' + LIMITE_MENCIONES + '.');
}

// El pie promete un número de planes y las diapositivas enseñan otro. Se comparan
// aquí, que es el único sitio del flujo donde están las dos cosas a la vez: el
// 3 de noviembre de 2026 el post decía "hay 10 planes" y llevaba 9.
const prometidos = pie.match(/\b(\d+)\s+planes?\b/);
if (prometidos && Number(prometidos[1]) !== p.imagenes.length) {
  throw new Error('El pie promete ' + prometidos[1] + ' planes y el paquete trae ' + p.imagenes.length + '.');
}

// ── Hijos ────────────────────────────────────────────────────────────────────
// La portada NO viene dentro de imagenes: son dos listas y el carrusel es la
// unión. Sin esto el post sale sin cara y nada lo avisa.
const todas = [p.portada, ...p.imagenes];
const urls = todas.slice(0, LIMITE_HIJOS);
const descartadas = todas.length - urls.length;

if (urls.length < 2) {
  throw new Error('Un carrusel necesita 2 imagenes como minimo y llegaron ' + urls.length + '.');
}

const vistos = new Set();
urls.forEach((url, i) => {
  if (typeof url !== 'string' || !url.startsWith('https://')) {
    throw new Error('La imagen ' + i + ' no es una URL https: ' + String(url));
  }
  if (vistos.has(url)) throw new Error('URL repetida en el carrusel: ' + url);
  vistos.add(url);
});

// ── Cupo ─────────────────────────────────────────────────────────────────────
// Si la lectura del cupo falló, se avisa y se sigue: un chequeo roto no puede
// impedir publicar. Si respondió y no queda cupo, sí se para.
let cupo = 'desconocido';
try {
  const bruto = $('Leer el cupo').first().json || {};
  if (bruto.error) {
    cupo = 'no se pudo leer (' + (bruto.error.message || 'sin detalle') + ')';
  } else {
    const fila = Array.isArray(bruto.data) ? (bruto.data[0] || {}) : bruto;
    const usado = Number(fila.quota_usage != null ? fila.quota_usage : bruto.quota_usage);
    const total = Number(
      (fila.config && fila.config.quota_total != null) ? fila.config.quota_total
        : (fila.quota_total != null ? fila.quota_total : bruto.quota_total)
    );
    if (Number.isFinite(total) && total > 0 && Number.isFinite(usado)) {
      cupo = usado + '/' + total;
      if (usado >= total) {
        throw new Error('Cupo de publicación agotado: ' + usado + ' de ' + total + ' en las últimas 24 h.');
      }
    }
  }
} catch (e) {
  // El throw del cupo agotado no se puede tragar con el catch de la lectura.
  if (String(e.message || '').startsWith('Cupo de publicación agotado')) throw e;
  cupo = 'no se pudo leer (' + (e.message || 'error') + ')';
}

return [{
  json: {
    simular,
    cupo,
    urls,
    total: urls.length,
    descartadas,
    titulos: p.titulos.slice(0, urls.length - 1),
    caption: pie,
    enlace: p.enlace,
    pieCaracteres: pie.length,
    etiquetas,
    menciones,
  },
}];

// La clave de idempotencia es el DÍA del pie, no el pie entero: el pie lleva
// dentro el número de planes ("hay 10 planes") y ese número cambia si la agenda
// cambia entre dos pasadas del mismo día. Comparando el pie completo, un plan
// nuevo a media mañana republicaba el carrusel. El día no cambia.
//
// Sale UN ITEM POR IMAGEN porque el nodo siguiente es el que crea los
// contenedores, y así se ahorra un nodo que sólo repartía la lista.
const paquete = $('Validar el paquete').first().json;

const norm = (t) => String(t || '').replace(/\s+/g, ' ').trim().toLowerCase();

// "Este martes 3 de noviembre hay 10 planes en Huesca." -> "este martes 3 de noviembre hay N planes en vitoria-huesca."
const claveDia = (t) => norm(String(t || '').split('\n')[0]).replace(/\b\d+\s+planes?\b/, 'N planes');

const nuevo = norm(paquete.caption);
const nuevaClave = claveDia(paquete.caption);

// Graph devuelve {data:[...], paging:{...}}: los medios están en data.
const bruto = $input.first().json || {};
const medios = Array.isArray(bruto.data) ? bruto.data : Array.isArray(bruto) ? bruto : [];

const repetido = medios.find((m) => {
  if (!m || !m.caption) return false;
  return norm(m.caption) === nuevo || (nuevaClave && claveDia(m.caption) === nuevaClave);
});

return paquete.urls.map((url, i) => ({
  json: {
    url,
    orden: i + 1,
    total: paquete.total,
    simular: paquete.simular,
    yaPublicado: Boolean(repetido),
    motivo: repetido
      ? 'Ese día ya está publicado (' + repetido.id + ', ' + (repetido.timestamp || 'sin fecha') + '). No se publica otra vez.'
      : 'Ninguno de los ' + medios.length + ' posts recientes es de hoy.',
    postExistente: repetido
      ? { id: repetido.id, permalink: repetido.permalink || null, timestamp: repetido.timestamp || null }
      : null,
    mediosRevisados: medios.length,
  },
}));

const d = $input.first().json;
return [{
  json: {
    publicado: false,
    motivo: d.motivo,
    postExistente: d.postExistente,
    mediosRevisados: d.mediosRevisados,
  },
}];

// Lo que se lee aquí es exactamente lo que se habría publicado. Sirve para
// revisar un día sin tocar la cuenta.
const p = $('Validar el paquete').first().json;
return [{
  json: {
    publicado: false,
    simulacro: true,
    diapositivas: p.total,
    descartadasPorLimite: p.descartadas,
    cupo: p.cupo,
    pieCaracteres: p.pieCaracteres,
    etiquetas: p.etiquetas,
    menciones: p.menciones,
    portada: p.urls[0],
    titulos: p.titulos,
    enlaceBio: p.enlace,
  },
}];

// El estado se pide de uno en uno, así que el bucle tiene que volver a entrar
// con un item por hijo y no con el item único de '¿Listos?'. Se reconstruyen
// desde 'Crear hijos', que es la lista de contenedores de verdad.
const hijos = $('Crear hijos').all().map((i) => i.json.id).filter(Boolean);
if (!hijos.length) throw new Error('No hay contenedores de imagen que comprobar.');
return hijos.map((id) => ({ json: { id } }));

// Un item de entrada por hijo, en el mismo orden en que se crearon: el nodo
// HTTP ejecuta los items de uno en uno y conserva el orden. Se empareja por
// índice y se contrasta el id cuando Meta lo devuelve, para que un desorden no
// haga leer el estado de un hijo como si fuera el de otro.
const ids = $('Crear hijos').all().map((i) => i.json.id).filter(Boolean);
const filas = $input.all().map((i) => i.json || {});

if (filas.length !== ids.length) {
  throw new Error('Se crearon ' + ids.length + ' hijos pero llegaron ' + filas.length + ' estados.');
}

const estados = ids.map((id, i) => {
  const fila = filas[i] || {};
  if (fila.id && String(fila.id) !== String(id)) {
    throw new Error('El estado ' + i + ' es del contenedor ' + fila.id + ' y se esperaba ' + id + '.');
  }
  return String(fila.status_code || 'DESCONOCIDO').toUpperCase();
});

const intentos = typeof $runIndex === 'number' ? $runIndex : 0;
const todosListos = estados.length > 0 && estados.every((e) => e === 'FINISHED');

if (!todosListos && estados.some((e) => e === 'ERROR' || e === 'EXPIRED')) {
  throw new Error('Meta rechazó contenedores de imagen: ' + estados.join(', ') + '.');
}
if (!todosListos && intentos >= 4) {
  throw new Error('Los hijos siguen sin estar listos tras ' + (intentos + 1) + ' comprobaciones: ' + estados.join(', ') + '.');
}
if (todosListos && ids.length !== estados.length) {
  throw new Error('Se crearon ' + ids.length + ' hijos pero se comprobaron ' + estados.length + '.');
}

return [{ json: { ids, todosListos, intentos: intentos + 1, estados } }];

// Publicar antes de FINISHED devuelve un error de Meta que no dice la causa
// real: el contenedor todavía se está montando.
const container = $('Crear carrusel').first().json.id;
const estado = String((($input.first() || {}).json || {}).status_code || 'DESCONOCIDO').toUpperCase();
const intentos = typeof $runIndex === 'number' ? $runIndex : 0;

if (estado === 'ERROR' || estado === 'EXPIRED') {
  throw new Error('Meta rechazó el carrusel ' + container + ': estado ' + estado + '.');
}

const listo = estado === 'FINISHED';
if (!listo && intentos >= 4) {
  throw new Error('El carrusel ' + container + ' sigue en ' + estado + ' tras ' + (intentos + 1) + ' comprobaciones.');
}

return [{ json: { id: container, estado, listo, intentos: intentos + 1 } }];

const post = $input.first().json || {};
const paquete = $('Validar el paquete').first().json;
const dia = String(paquete.urls[0] || '').match(/\/(\d{4}-\d{2}-\d{2})\//);

if (!post.id) {
  throw new Error('Se publicó pero Meta no devolvió el id del post: no se puede dar la URL.');
}

return [{
  json: {
    publicado: true,
    postId: post.id,
    permalink: post.permalink || null,
    publicadoEl: post.timestamp || null,
    dia: dia ? dia[1] : null,
    diapositivas: paquete.total,
    descartadasPorLimite: paquete.descartadas,
    cupo: paquete.cupo,
    enlaceBio: paquete.enlace,
    pie: paquete.caption,
  },
}];
